-- ===== Tabel: users =====
CREATE TABLE users (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    username      TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    salt          TEXT NOT NULL,
    nama          TEXT NOT NULL,
    role          TEXT NOT NULL DEFAULT 'staf',   -- admin | gudang | kasir
    aktif         INTEGER NOT NULL DEFAULT 1
);


-- ===== Tabel: supplier =====
CREATE TABLE supplier (
    id      INTEGER PRIMARY KEY AUTOINCREMENT,
    nama    TEXT NOT NULL,
    kontak  TEXT,
    telepon TEXT,
    alamat  TEXT,
    aktif   INTEGER NOT NULL DEFAULT 1
);


-- ===== Tabel: bahan =====
CREATE TABLE bahan (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    kode       TEXT NOT NULL UNIQUE,
    nama       TEXT NOT NULL,
    satuan     TEXT NOT NULL,
    stok       REAL NOT NULL DEFAULT 0,
    stok_min   REAL NOT NULL DEFAULT 0,
    harga_beli REAL NOT NULL DEFAULT 0,   -- harga rata-rata bergerak per satuan
    aktif      INTEGER NOT NULL DEFAULT 1
);


-- ===== Tabel: produk =====
CREATE TABLE produk (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    kode       TEXT NOT NULL UNIQUE,
    nama       TEXT NOT NULL,
    kategori   TEXT,
    harga_jual REAL NOT NULL DEFAULT 0,
    stok       REAL NOT NULL DEFAULT 0,
    stok_min   REAL NOT NULL DEFAULT 0,
    aktif      INTEGER NOT NULL DEFAULT 1
);


-- ===== Tabel: resep =====
CREATE TABLE resep (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    produk_id INTEGER NOT NULL REFERENCES produk(id) ON DELETE CASCADE,
    bahan_id  INTEGER NOT NULL REFERENCES bahan(id) ON DELETE CASCADE,
    qty       REAL NOT NULL,
    UNIQUE (produk_id, bahan_id)
);


-- ===== Tabel: pembelian =====
CREATE TABLE pembelian (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    no_po       TEXT NOT NULL UNIQUE,
    tanggal     TEXT NOT NULL,
    supplier_id INTEGER NOT NULL REFERENCES supplier(id),
    total       REAL NOT NULL DEFAULT 0,
    status      TEXT NOT NULL DEFAULT 'draft',   -- draft | diterima
    user_id     INTEGER REFERENCES users(id),
    created_at  TEXT NOT NULL
);


-- ===== Tabel: pembelian_item =====
CREATE TABLE pembelian_item (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    pembelian_id INTEGER NOT NULL REFERENCES pembelian(id) ON DELETE CASCADE,
    bahan_id     INTEGER NOT NULL REFERENCES bahan(id),
    qty          REAL NOT NULL,
    harga        REAL NOT NULL,
    subtotal     REAL NOT NULL
);


-- ===== Tabel: produksi =====
CREATE TABLE produksi (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    no_batch    TEXT NOT NULL UNIQUE,
    tanggal     TEXT NOT NULL,
    produk_id   INTEGER NOT NULL REFERENCES produk(id),
    qty         REAL NOT NULL,
    biaya_bahan REAL NOT NULL DEFAULT 0,
    user_id     INTEGER REFERENCES users(id),
    catatan     TEXT,
    created_at  TEXT NOT NULL
);


-- ===== Tabel: produksi_item =====
CREATE TABLE produksi_item (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    produksi_id INTEGER NOT NULL REFERENCES produksi(id) ON DELETE CASCADE,
    bahan_id    INTEGER NOT NULL REFERENCES bahan(id),
    qty         REAL NOT NULL,
    harga       REAL NOT NULL,
    subtotal    REAL NOT NULL
);


-- ===== Tabel: penjualan =====
CREATE TABLE penjualan (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    no_invoice TEXT NOT NULL UNIQUE,
    tanggal    TEXT NOT NULL,
    subtotal   REAL NOT NULL DEFAULT 0,
    diskon     REAL NOT NULL DEFAULT 0,
    total      REAL NOT NULL DEFAULT 0,
    hpp        REAL NOT NULL DEFAULT 0,
    metode     TEXT NOT NULL DEFAULT 'Tunai',
    user_id    INTEGER REFERENCES users(id),
    created_at TEXT NOT NULL
);


-- ===== Tabel: penjualan_item =====
CREATE TABLE penjualan_item (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    penjualan_id INTEGER NOT NULL REFERENCES penjualan(id) ON DELETE CASCADE,
    produk_id   INTEGER NOT NULL REFERENCES produk(id),
    qty         REAL NOT NULL,
    harga       REAL NOT NULL,
    subtotal    REAL NOT NULL,
    hpp         REAL NOT NULL DEFAULT 0
);


-- ===== Tabel: pengeluaran =====
CREATE TABLE pengeluaran (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    tanggal    TEXT NOT NULL,
    kategori   TEXT NOT NULL,
    keterangan TEXT,
    jumlah     REAL NOT NULL,
    user_id    INTEGER REFERENCES users(id)
);


-- ===== Tabel: kas =====
CREATE TABLE kas (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    tanggal    TEXT NOT NULL,
    tipe       TEXT NOT NULL,        -- masuk | keluar
    kategori   TEXT NOT NULL,
    ref_tipe   TEXT,                 -- penjualan | pembelian | pengeluaran
    ref_id     INTEGER,
    keterangan TEXT,
    jumlah     REAL NOT NULL,
    created_at TEXT NOT NULL
);


-- ===== Tabel: audit =====
CREATE TABLE audit (
    id     INTEGER PRIMARY KEY AUTOINCREMENT,
    waktu  TEXT NOT NULL,
    user   TEXT,
    aksi   TEXT NOT NULL,
    detail TEXT
);

